<script>document.addEventListener('DOMContentLoaded',()=>{let s=0,p=[...document.querySelectorAll('.emp-panel')],m=[...document.querySelectorAll('.step-btn')],prev=document.querySelector('#prev'),next=document.querySelector('#next'),save=document.querySelector('#save');function show(){p.forEach((x,i)=>x.classList.toggle('active',i===s));m.forEach((x,i)=>{x.classList.toggle('active',i===s);x.classList.toggle('done',i<s)});prev.style.visibility=s?'visible':'hidden';next.style.display=s===4?'none':'block';save.style.display=s===4?'block':'none'}next.onclick=()=>{for(const f of p[s].querySelectorAll('input,select'))if(!f.checkValidity()){f.reportValidity();return}s++;show()};prev.onclick=()=>{s--;show()};show()})</script>
